import { readFile } from "node:fs/promises";

export function readOverlayScript(): Promise<Buffer> {
  return readFile(new URL("./live-games-overlay.js", import.meta.url));
}

export function overlayDocument(nonce: string): string {
  // The nonce is generated by the Host per response.
  return `<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bycoda Halay</title>
<style nonce="${nonce}">
  :root {
    color-scheme: dark;
    font-family: system-ui, sans-serif;
    --backdrop: oklch(18% .026 176);
    --panel: oklch(23% .04 177 / .92);
    --gold: oklch(83% .107 77);
    --title: oklch(91% .101 84);
    --ink: oklch(95% .055 86);
    --muted: oklch(85% .044 132);
    --border: color-mix(in oklch, var(--gold) 46%, transparent);
  }
  * { box-sizing: border-box; }
  body { margin: 0; display: grid; place-items: center; block-size: 100dvh; overflow: clip; background: var(--backdrop); }
  #stage { position: relative; block-size: min(100dvh, 177.778vw); inline-size: min(100vw, 56.25dvh); container-type: size; isolation: isolate; }
  #stage[data-wide] { block-size: min(100dvh, 56.25vw); inline-size: min(100vw, 177.778dvh); }
  canvas { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; }
  #heading { position: absolute; inset-block-start: 6%; inset-inline: 8%; text-align: center; }
  h1 { margin: 0; font: 700 clamp(2rem, 1rem + 12cqmin, 8.5rem)/0.96 Georgia, serif; letter-spacing: -0.065em; color: var(--title); }
  #stage[data-wide] h1 { font-size: clamp(2rem, 1rem + 7cqmin, 7rem); }
  #details { margin: 1em 0 0; color: var(--muted); font-weight: 650; font-size: clamp(.75rem, .55rem + 1.3cqmin, 1.65rem); }
  #score, #ticker { position: absolute; padding: .85em 1em; border: 1px solid var(--border); border-radius: .65em; background: var(--panel); color: var(--ink); font-size: clamp(.75rem, .55rem + 1.3cqmin, 1.65rem); }
  #score { inset-block-end: 8%; inset-inline: 8%; }
  #ticker { inset-block-end: 2%; inset-inline: 8%; display: flex; gap: .65em; align-items: baseline; overflow: clip; }
  #stage[data-wide] #score { inset-block-end: 14%; inset-inline: 3% auto; inline-size: 18%; }
  #stage[data-wide] #ticker { inset-inline: 25%; }
  h2 { margin: 0; color: var(--gold); font-size: .72em; font-weight: 750; letter-spacing: .12em; text-transform: uppercase; flex: none; }
  #leaders { margin: .45em 0 0; padding-inline-start: 1.5em; }
  #leaders li { display: list-item; padding: .1em 0; }
  #leaders li > span { float: inline-end; margin-inline-start: .45em; color: var(--gold); font-variant-numeric: tabular-nums; }
  #gift, #leaders li { white-space: nowrap; overflow: clip; text-overflow: ellipsis; }
  #sound { position: absolute; inset-inline-end: 3%; inset-block-start: 2%; border: 1px solid var(--border); background: var(--panel); color: var(--ink); border-radius: .65em; padding: .5em .75em; cursor: pointer; font: 650 clamp(.75rem, .55rem + .9cqmin, 1.4rem) system-ui, sans-serif; }
  #sound:focus-visible { outline: 2px solid var(--title); outline-offset: 2px; }
  #sound:active { transform: scale(.97); }
  [hidden] { display: none !important; }
  #stage[data-clean] #heading, #stage[data-clean] aside, #stage[data-clean] #sound { display: none; }
</style>
<script src="overlay.js" defer></script>
</head>
<body>
<main id="stage">
  <canvas id="scene" role="img" aria-label="Halay sahnesi"></canvas>
  <header id="heading"><h1>Halay</h1><p id="details"></p></header>
  <aside id="score" hidden><h2 id="score-title">Hediye sıralaması</h2><ol id="leaders"></ol></aside>
  <aside id="ticker" hidden><h2 id="gift-title">Son hediye</h2><span id="gift"></span></aside>
  <button id="sound" type="button"></button>
</main>
</body>
</html>`;
}
